using ChartForgeX.Interactivity.Html;
using ChartForgeX.Typography;
internal static class NativeJointValuesVisibilityExamples {
    internal static void Write(string output,string[] args){var font=NativeFallbackRadialExamples.RequiredFont(args,"--primary-font");FontRegistry.Register("Native joint font",font);Directory.CreateDirectory(output);var renderer=new HtmlInteractiveChartRenderer();foreach(var bar in new[]{false,true})foreach(var width in new[]{390,760}){var mode=width==390?VisualThemeMode.Light:VisualThemeMode.Dark;var from=renderer.PrepareVisibilitySection(NativeJointValuesVisibilityRecipe.Create(bar,30,width,mode,"Native joint font"),NativeJointValuesVisibilityRecipe.View(false));var to=renderer.PrepareVisibilitySection(NativeJointValuesVisibilityRecipe.Create(bar,40,width,mode,"Native joint font"),NativeJointValuesVisibilityRecipe.View(true));var payload=renderer.PrepareNativeTransitionJson(from,to,new HtmlNativeTransitionOptions(HtmlNativeTransitionEffect.ValuesAndVisibility,5));var prefix=Path.Combine(output,"native-joint-"+bar+"-"+width);File.WriteAllText(prefix+".from.html",from.Html);File.WriteAllText(prefix+".to.html",to.Html);File.WriteAllText(prefix+".transition.json",payload);File.WriteAllText(prefix+".from.svg",from.PreparedVisual.ToSvg());File.WriteAllBytes(prefix+".from.png",from.PreparedVisual.ToPng());File.WriteAllText(prefix+".to.svg",to.PreparedVisual.ToSvg());File.WriteAllBytes(prefix+".to.png",to.PreparedVisual.ToPng());File.WriteAllText(prefix+".program.cs",ExampleRecipeSource.EmitNativeJointValuesVisibility(bar,width,mode));}}
}
